UPDATE CONVERSATIONS
SET updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}

UPDATE CONVERSATIONS
SET title = #{title},
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'

UPDATE CONVERSATIONS
SET status = 'DELETED',
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'
